    // is reasonable for the actual machine SIMD width.
    const int vec = 8;

    // x and b are 1-D; vectorize their inner loop.
    init_x.compute_root()
          .vectorize(i, vec);
    init_b.compute_root()
          .vectorize(i, vec);

    // L is 2-D. We store as L(j, i) so j is the fast-varying dim.
    // Parallelize over rows (i) and vectorize over columns (j) to
    // get good cache behavior and SIMD utilization.
    init_L.compute_root()
          .parallel(i)
          .vectorize(j, vec);

    // Realize into the provided Buffers.
    init_x.realize(x);
    init_b.realize(b);
    init_L.realize(L);
}

int main(int argc, char *argv[]) {
    // problem size
    int n = N;

    // Buffers:
    // L: original is L[i][j]; we store as L(j, i) so that the first
    // dimension (j) is the fast-varying one.
    Halide::Buffer<num_t, 2> L(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> b(n);

    // ImageParams corresponding to L, x, b
    ImageParam L_param(type_of<num_t>(), 2, "L_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam b_param(type_of<num_t>(), 1, "b_param");

    // Scalar Param for the current row index i
    Param<int> i_param("i_param");

    // Scalar Param for the diagonal value L[i][i], which is constant
    // across all i due to how init_array initializes L.
    Param<num_t> diag_param("diag_param");

    // initialize data
    init_array(n, L, x, b);

    // Precompute the diagonal value once on the host:
    //
    // In init_array, for j == i, we have:
    //   L[i][i] = (i + n - i + 1) * 2 / n = (n + 1) * 2 / n
    //
    // We replicate the same arithmetic here so that dividing by
    // L[i][i] is equivalent to dividing by this constant, but avoids
    // loading it every iteration inside the Halide pipeline.
    num_t diag_val = (static_cast<num_t>(n + 1) * static_cast<num_t>(2)) /
                     static_cast<num_t>(n);
    diag_param.set(diag_val);

