    xi() = b_param(i_param);

    // Subtract contributions L[i][j] * x[j]
    // Recall: L[i][j] is stored as L_param(j, i_param)
    xi() -= L_param(r, i_param) * x_param(r);

    // Divide by the (constant) diagonal entry L[i][i]
    xi_div() = xi() / diag_param;

    // --------------------------
    // Scheduling for the kernel
    // --------------------------
    // Bind ImageParams to our Buffers (x is updated on the host and
    // the ImageParam always points at the current contents).
    L_param.set(L);
    x_param.set(x);
    b_param.set(b);

    // Use a modest vector width for the reduction over j. Halide will
    // handle non-multiple-of-vec extents by generating a scalar tail
    // loop. This keeps the per-i inner product efficient.
    const int vec = 8;
    RVar r_j = r.x;
    xi.update()
        .vectorize(r_j, vec);

