    target.set_feature(Target::NoAsserts);
    target.set_feature(Target::NoBoundsQuery);
    xi_div.compile_jit(target);

    // Reuse a scalar output buffer for xi_div() across all iterations
    // to avoid repeated small heap allocations.
    Halide::Buffer<num_t> xi_buf = Halide::Buffer<num_t>::make_scalar();

