    // Schedule for initialization
    //
    // We parallelize across the outer index (i: rows) and vectorize
    // across the inner index (j: columns) to get good cache behavior
    // and exploit SIMD. The exact vector width is a heuristic; Halide
    // will handle any tail iterations safely.
    // ------------------------------------------------------------------
    const int vec_width = 8;  // Reasonable SIMD width for modern x86; safe on all targets.

    // Initialize x and b: 1-D, parallel over i and vectorize it.
    init_x
        .compute_root()
        .vectorize(i, vec_width)
        .parallel(i);

    init_b
        .compute_root()
        .vectorize(i, vec_width)
        .parallel(i);

    // Initialize L: 2-D, parallel over rows (i), vectorize along j (contiguous).
    init_L
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    // Realize into the given buffers. The first call to realize for each
    // Func JIT-compiles its code; subsequent calls reuse the compiled code.
    init_x.realize(x);
    init_b.realize(b);
    init_L.realize(L);
}

