    // accumulator, but we can still expose some instruction-level
    // parallelism by unrolling a small fixed factor. Because i_param
    // is a runtime value, the reduction extent is dynamic, but Halide
    // will generate appropriate tail handling when we partially unroll.
    // -----------------------------------------------------------------
    xi.compute_root();
    xi.update()
        .unroll(r, 4);  // small unroll factor to reduce loop overhead and expose ILP

