    Target target = get_jit_target_from_environment();

    // JIT-compile the pipeline once for this target
    xi_div.compile_jit(target);

    // -----------------------------------------------------------------
    // Run the triangular solve, timing only the kernel-like part:
    // -----------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // Set current row index
        i_param.set(i);

        // Realize scalar xi_div() for this i.
        // This reuses the already-JIT-compiled code; only the scalar
