#include <chrono>
#include <iomanip>
#include <iostream>

#include "Halide.h"

// include common definitions (e.g. N, DATA_TYPE)
#include "defines.hpp"

// include benchmark-specific definitions (same role as trisolv.h)
#include "trisolv.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/* Array initialization translated to Halide. */
static
void init_array(int n,
                Halide::Buffer<num_t, 2> L,  // logical L[i][j] stored as L(j, i)
                Halide::Buffer<num_t, 1> x,
                Halide::Buffer<num_t, 1> b) {
    Var i("i"), j("j");
    Func init_x("init_x"), init_b("init_b"), init_L("init_L");

    // x[i] = -999;
    init_x(i) = cast<num_t>(Expr(-999));

    // b[i] = i;
    init_b(i) = cast<num_t>(i);

    // L[i][j] = (DATA_TYPE) (i+n-j+1)*2/n for j <= i; 0 elsewhere (unused in kernel).
    // Remember: L is stored as L(j, i) (j = column, i = row) to make j the fast-varying dim.
    Expr n_expr = cast<num_t>(Expr(n));
    Expr two    = cast<num_t>(Expr(2));

    init_L(j, i) = select(j <= i,
                          (cast<num_t>(i + n - j + 1) * two) / n_expr,
                          cast<num_t>(Expr(0)));

    // -----------------------
    // Scheduling for init_* :
    // -----------------------
    // We parallelize across rows and vectorize along the innermost dimension
    // to get good memory throughput for large n. Initialization is done once,
    // but for realistic problem sizes it is still worth optimizing.

    Target host_target = get_host_target();
    const int vec_width = natural_vector_size(host_target, type_of<num_t>());

    // 1D initializations for x and b: contiguous in i.
    // Parallelize across i and vectorize along i.
    init_x
        .compute_root()
        .vectorize(i, vec_width)
        .parallel(i);

    init_b
        .compute_root()
        .vectorize(i, vec_width)
        .parallel(i);

    // 2D initialization for L: j is the fast-varying dimension.
    // Parallelize across rows (i) and vectorize in j.
    Var j_outer("j_outer"), j_inner("j_inner");
    init_L
        .compute_root()
        .split(j, j_outer, j_inner, vec_width)
        .vectorize(j_inner)
        .parallel(i);

    // Realize into the provided buffers.
    init_x.realize(x);
    init_b.realize(b);
    init_L.realize(L);
}

int main(int argc, char *argv[]) {
    // problem size
    int n = N;

    // Buffers:
    // L: original is L[i][j]; we store as L(j, i) so that the first
    // dimension (j) is the fast-varying one.
    Halide::Buffer<num_t, 2> L(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> b(n);

    // ImageParams corresponding to L, x, b
    ImageParam L_param(type_of<num_t>(), 2, "L_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam b_param(type_of<num_t>(), 1, "b_param");

    // Scalar Param for the current row index i
    Param<int> i_param("i_param");

    // initialize data
    init_array(n, L, x, b);

    // -----------------------------------------------------------------
    // Halide formulation of the inner computation:
    //
    // For a fixed i:
    //   x[i] = b[i];
    //   for (j = 0; j < i; j++)
    //       x[i] -= L[i][j] * x[j];
    //   x[i] = x[i] / L[i][i];
    //
    // We express the j-loop as a reduction over RDom, and drive the
    // i-loop from the host, updating x one element at a time.
    // -----------------------------------------------------------------

    Func xi("xi");         // accumulates b[i] - sum_{j<i} L[i][j]*x[j]
    Func xi_div("xi_div"); // final x[i] = xi / L[i][i]

    // RDom over j = 0 .. i_param-1
    RDom r(0, i_param, "r");

    // Start from b[i]
    xi() = b_param(i_param);

    // Subtract contributions L[i][j] * x[j]
    // Recall: L[i][j] is stored as L_param(j, i_param)
    xi() -= L_param(r, i_param) * x_param(r);

    // Divide by the diagonal entry L[i][i] (L_param(i, i))
    xi_div() = xi() / L_param(i_param, i_param);

    // -----------------------
    // Scheduling for xi/xi_div
    // -----------------------
    // The i-loop is inherently sequential (x[i] depends on all x[j<i]),
    // so we keep the outer i-loop on the host. Inside each iteration,
    // xi is just a dot product along r. We improve its throughput by:
    //  - computing xi at root (scalar reduction),
    //  - vectorizing the reduction variable r.
    {
        Target host_target = get_host_target();
        const int vec_width = natural_vector_size(host_target, type_of<num_t>());

        RVar r_outer("r_outer"), r_inner("r_inner");

        // Scalar reduction, executed once per i.
        xi.compute_root();

        // Vectorize the inner part of the reduction over r. Halide
        // will generate vector loads from L_param(j,i) and x_param(j),
        // which both have unit stride in j.
        xi.update()
            .split(r.x, r_outer, r_inner, vec_width)
            .vectorize(r_inner);

        // xi_div is also scalar; compute it at root.
        xi_div.compute_root();
    }

    // Bind ImageParams to our Buffers
    L_param.set(L);
    x_param.set(x);
    b_param.set(b);

    // JIT-compile the pipeline once
    xi_div.compile_jit();

    // Pre-allocate a scalar buffer to avoid per-iteration allocation
    Buffer<num_t> xi_buf;  // 0-dim scalar buffer; size 1, reused every call

    // -----------------------------------------------------------------
    // Run the triangular solve, timing only the kernel-like part:
    // -----------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // Set current row index
        i_param.set(i);

        // Realize scalar xi_div() for this i into our reusable buffer
        xi_div.realize(xi_buf);

        // Update x[i] on the host
        x(i) = xi_buf();
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -----------------------------------------------------------------
    // Print results (similar style to example/gemm.cpp)
    // -----------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            std::cerr << x(i) << '\n';
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
